const body = $input.first().json.body || $input.first().json;
const toolCallList = body?.message?.toolCallList || [];
const toolCall = toolCallList[0] || {};
const toolCallId = toolCall.id || 'unknown';
let args = {};
try { args = JSON.parse(toolCall.function?.arguments || '{}'); } catch(e) { args = {}; }
return [{ json: { toolCallId, doctorName: args.doctorName || '', preferredDate: args.preferredDate || '', preferredTime: args.preferredTime || '' } }];

const toolCallId = $('Argümanları Çıkar').first().json.toolCallId;
const doctorName = $('Argümanları Çıkar').first().json.doctorName;
const preferredDate = $('Argümanları Çıkar').first().json.preferredDate;
const preferredTime = $('Argümanları Çıkar').first().json.preferredTime;
const conflicts = $input.all().map(i => i.json).filter(r => r.id);

if (conflicts.length === 0) {
  return [{ json: { toolCallId, result: `${doctorName} doktoru ${preferredDate} tarihinde ${preferredTime || '09:00-18:00 saatleri arasında'} müsait. Randevu oluşturabilirsiniz.` } }];
}

const bookedTimes = conflicts.map(c => c.appointment_time).join(', ');
return [{ json: { toolCallId, result: `${doctorName} doktorunun ${preferredDate} tarihinde şu saatleri dolu: ${bookedTimes}. Farklı bir saat veya tarih tercih eder misiniz?` } }];
